//! The frozen tile sets, one per language. Generated by
//! `wordwarz-lexicon tiles` (see `TileSet::derive`); never edit by hand,
//! and never regenerate a set in place: a changed set is a new rules version.

use crate::letters::ALPHABET;
use crate::lexicon::Language;
use crate::tiles::TileSet;

pub fn for_language(language: Language) -> &'static TileSet {
    match language {
        Language::Dutch => &DUTCH,
        Language::English => &ENGLISH,
        Language::Bilingual => &BILINGUAL,
    }
}

const fn set(counts: [u8; ALPHABET], values: [u8; ALPHABET]) -> TileSet {
    TileSet { counts, values, blanks: 2 }
}

